import { createContext, useContext } from 'react'

export interface RootProviderData {
    isBranded: boolean
    portalElement?: HTMLElement | null
}

export const RootProviderContext = createContext<RootProviderData>({
    isBranded: false,
    portalElement: null,
})

export function useWildcardRootProvider(): RootProviderData {
    return useContext(RootProviderContext)
}
