export interface Pass<T> {
    ok: true
    value: T
}

export interface Fail<E = Error> {
    ok: false
    error: E
}

/**
 * This type represents the outcome of an operation that can either succeed or fail.
 */
export type Result<T, E = Error> = Pass<T> | Fail<E>

function pass(): Pass<void>
function pass<T>(value: T): Pass<T>
function pass<T>(value?: T): Pass<any> {
    if (arguments.length === 0) {
        return { ok: true, value: undefined }
    }
    return { ok: true, value }
}

export const Result = {
    /**
     * Creates a successful Result.
     *
     * No argument has to be passed to the method if Tis void. I.e. both of
     * these are valid:
     *
     * Result.pass(42) // Result<number>
     * Result.pass() // Result<void>
     */
    pass,
    /**
     * Creates a failed Result.
     */
    fail<E = Error>(error: E): Fail<E> {
        return { ok: false as const, error }
    },
}

/**
 * unwrap returns the value form result, if result is Pass<T>, or the
 * default value.
 *
 * @param result the {@link Result} to unwrap
 * @param defaultValue the value to return if `result` is not {@link Pass}
 * @returns The unwrapped result or the default value
 */
export function unwrapOr<T, E>(result: Result<T, E>, defaultValue: T): T {
    return result.ok ? result.value : defaultValue
}

export function isResult(value: unknown): value is Result<unknown> {
    return !!value && typeof value === 'object' && 'ok' in value && ('value' in value || 'error' in value)
}
