import { createContext, useContext } from 'react'

import { useWildcardRootProvider } from '../../RootProvider'

interface PopoverRootData {
    renderRoot: HTMLElement | null
}

const DEFAULT_POPOVER_PROVIDER_INFO: PopoverRootData = {
    renderRoot: null,
}

export const PopoverRoot = createContext<PopoverRootData>(DEFAULT_POPOVER_PROVIDER_INFO)

export function usePopoverContext(): PopoverRootData {
    const { portalElement } = useWildcardRootProvider()
    const popoverContext = useContext(PopoverRoot)

    return { ...popoverContext, renderRoot: popoverContext.renderRoot ?? portalElement ?? null }
}
